            List<string> pieces = new();
            int i = 0;
            while (i < text.Length) {
                while (i < text.Length && Value.Whitespace(text[i])) i++;
                int start = i;
                while (i < text.Length && !Value.Whitespace(text[i])) i++;
                if (i > start) pieces.Add(text[start..i]);
            } return pieces;
        }
